            /** @description true = carteira de simulação. */
            exclude_from_consolidated?: boolean;
            /** @description Linhas devolvidas em holdings[] (abertas + encerradas + watchlist). */
            holdings_count?: number;
            /** @description Posições com quantidade > 0. */
            open_positions?: number;
            /** @description Posições zeradas por venda (qty = 0 com transações). */
            closed_positions?: number;
            /** @description Entradas sem nenhuma transação (radar). */
            watchlist_entries?: number;
            /** @description Tickers predecessores fundidos nas posições por sucessão. Contam em ledger_assets (listPortfolios) e não em holdings_count — é a diferença entre as duas contagens. */
            merged_assets?: number;
            patrimonio?: number;
            invested?: number;
            unrealized_pl?: number;
            unrealized_pct?: number;
            realized_pl?: number;
            realized_by_month?: {
                [key: string]: number;
            };
            income_received?: number;
            income_by_month?: {
                [key: string]: number;
            };
            /** @description unrealized_pl + realized_pl. */
            total_pl?: number;
            /** @description XIRR (TIR anualizada, money-weighted): o retorno REAL do investidor sobre os fluxos datados (aportes/resgates/proventos) + patrimônio a mercado como valor terminal. Decimal a.a. (0,1423 = 14,23%). null quando custo desconhecido, fluxo sem TIR definível ou implausível (> +300% a.a., artefato de giro/curto prazo → use o twr). Mesmo valor de returns.xirr, onde ele aparece ao lado do time-weighted. */
            xirr?: number | null;
            returns?: components["schemas"]["PortfolioReturns"];
            day_change_brl?: number;
            day_change_pct?: number;
            /** @description Resumo humano, ex.: '3 ações · 2 FIIs'. */
            kind_mix?: string;
